INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('imane-ayissi', 'Imane Ayissi', 'Couturier, Cameroun (Paris)', 'Couturier, Cameroon (Paris)', 'Né au Cameroun, ancien danseur du Ballet national, Imane Ayissi vit à Paris depuis les années 1990. Sa maison de haute couture puise dans les fibres naturelles, les tissages et les teintures végétales du continent africain, et présente ses collections à la Fashion Week de haute couture parisienne depuis 2020.', 'Born in Cameroon and a former dancer with the National Ballet, Imane Ayissi has lived in Paris since the 1990s. His couture house draws on natural fibres, weaving and plant dyes from across Africa, and has shown at Paris Haute Couture Week since 2020.', '/images/examples/veste-tiedye.webp', 'https://imane-ayissi.com/en/pages/la-maison')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('ldm-look-different-marque', 'LDM (Look Different Marque)', 'Maison de mode, Lagos, Nigeria', 'Fashion house, Lagos, Nigeria', 'Fondée en 2021 par Munachimso Okolo, LDM est une marque nigériane contemporaine. Les tissus sont choisis dans le monde entier et chaque pièce, sur mesure ou prêt-à-porter, est confectionnée dans l''atelier de Lagos.', 'Founded in 2021 by Munachimso Okolo, LDM is a contemporary Nigerian brand. Fabrics are sourced worldwide and every piece, bespoke or ready-to-wear, is made in the Lagos fashion house.', '/images/examples/veste-verte-portee.webp', 'https://ldmclo.com/about-us/')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('loza-maleombho', 'Lozama Leombho', 'Créatrice de mode, Côte d''Ivoire / États-Unis', 'Fashion designer, Côte d''Ivoire / United States', 'Née au Brésil en 1985 et élevée entre la Côte d''Ivoire et les États-Unis, Loza Maléombho est diplômée en animation. Elle réinterprète les récits et l''artisanat d''Afrique de l''Ouest en silhouettes sculpturales et géométriques, à la croisée de la mode, de l''image et des nouvelles technologies.', 'Born in Brazil in 1985 and raised between Côte d''Ivoire and the United States, Loza Maléombho trained in animation. She reinterprets West African stories and craftsmanship in sculptural, geometric silhouettes, at the crossroads of fashion, image and new technologies.', '/images/examples/ceinture-cuir.webp', 'https://www.lozamaleombho.com/about')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('house-of-marjon', 'House of Marjón', 'Accessoires', 'Accessories', 'House of Marjón est une maison de design et une marque de mode nigériane, fondée et dirigée par Abdulazeez Sani Ibrahim. Elle est connue pour ses lunettes et ses masques sculpturaux faits main, associant fil de cuivre plaqué or, perles d''eau douce, cristaux et cauris. Son univers mêle héritage africain, géométrie sacrée, spiritualité et design d''avant-garde. Présentation indicative, à confirmer avec la maison.', 'House of Marjón is a Nigerian design house and fashion brand, founded and led by Abdulazeez Sani Ibrahim. It is known for handmade eyewear and sculptural masks that combine gold-plated copper wire, freshwater pearls, cut crystals and cowrie shells. Its universe blends African heritage, sacred geometry, spirituality and avant-garde design. Indicative description, to be confirmed with the house.', '/images/examples/marjon-lunettes-cristaux.webp', '')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
